package com.deniscerri.ytdl.util

/**
 * Builds the Netscape cookie file that is handed to yt-dlp through --cookies.
 *
 * The stored cookie entries also carry the metadata comments that were written when
 * they were captured ("# <url>" and "# Generated by YTDLnis"). Those comments are not
 * Netscape cookie rows, so they are dropped here. De-duplication is done on the exact
 * cookie row, so two entries for the same site keep their own cookies instead of one
 * of them shadowing the other.
 */
object CookieFileBuilder {

    /**
     * Netscape cookie files use this prefix to mark a cookie as HTTP only. Such a line
     * is a cookie row and not a comment, so it must not be dropped.
     */
    private const val HTTP_ONLY_PREFIX = "#HttpOnly_"

    /**
     * Header of a Netscape cookie file. Kept in one place so the file that is written
     * and the header that is used for clipboard import/export never drift apart.
     */
    const val HEADER =
        "# Netscape HTTP Cookie File\n" +
                "# WebView Generated by the YTDLnis app\n" +
                "# This is a generated file! Do not edit.\n"

    /**
     * @param cookieContents the raw content of every cookie entry that should be written.
     * @return the full contents of the Netscape cookie file.
     */
    fun build(cookieContents: List<String>): String {
        val cookieLines = linkedSetOf<String>()

        cookieContents.forEach { content ->
            content.lines().forEach { line ->
                val cookieLine = line.trim()
                if (cookieLine.isNotEmpty() &&
                    (!cookieLine.startsWith("#") || cookieLine.startsWith(HTTP_ONLY_PREFIX))
                ) {
                    cookieLines.add(cookieLine)
                }
            }
        }

        return buildString {
            append(HEADER)
            cookieLines.forEach { cookieLine ->
                append(cookieLine)
                append("\n")
            }
        }
    }
}
